sort=[];
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});

	bd=["必读榜","潜力榜","完本榜","更新榜","搜索榜","评论榜"];
	[["男频","1"],["女频","2"]].map([title,id]=>{
push(title+'榜单', null, 1, 1);
		bd.map((title,index)=>{			
		  	url= `/module/rank?type=${index+1}&channel=${id}&page={{page}}`; 
				push(title, url, 1, 0.25);										
			});
	});


  fl=	[["男频","1"],["女频","2"]].map([title,id]=>{
url= `http://api.xingliangglobal.com/novel/category?channel=${id}`;
return	 	data=JSON.parse(java.ajax(url)).data.categories;
				});
	 [["男频",fl[0]],["女频",fl[1]]].map([tit1,category]=>{
	 		[["连载","0"],["完结","1"]].map([tit2,id]=>{  
	    push(tit1+'🍁'+tit2, null, 1, 1);

     category.map(($)=>{

	    title=$.categoryName;
     	cid=$.categoryId;
	url= `/novel?isComplete=${id}&sort=1&page={{page}}&categoryId=${cid}`;

			 	push(title, url, 1, 0.25);
        });
      });
  });
JSON.stringify(sort);

